INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('8d23caa34d96cec7', 'act_1033194534145987', 'Show it, don''t say it', 'Trades, quizzes, label reads, six-second loops. Your hands are doing something before you say a word.', 'sparkles', '<path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"/><path d="M20 2v4"/><path d="M22 4h-4"/><circle cx="4" cy="20" r="2"/>', '#0F766E', 1, 0, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('15a6960be5c2e9ac', 'act_1033194534145987', '4942d9a1c63d1254', 0, 0, 1, 'live', 'Scary good night, less scary morning', 'The grown-up costume party is her night, and the pumpkin patch with the kids at 9 still happens.', 'The mom going to an adult Halloween party with the family pumpkin patch booked for the morning.', 'Halloween bundle', 'Split screen', NULL, '["Scary good night. Less scary morning. Same witch.", "Costume party tonight. Pumpkin patch at nine. Yes, with the kids.", "Me at ten pm versus me at nine am. Guess which one planned ahead."]', '[{"label": "Open · 0 to 3s", "text": "The split: party left, pumpkin patch right, both clocks on screen."}, {"label": "Middle", "text": "Back to the mirror: patch on, close enough to read the design, then the costume finished over it."}, {"label": "Close", "text": "The pumpkin patch. You lift the biggest one like it is nothing. Pack in your coat pocket."}]', 'TONIGHT: Halloween party / TOMORROW: pumpkin patch, 9AM', 'Put both times on screen. The clock is the whole story.', 'Show the morning from bed. She is up and lifting pumpkins.', NULL, 'Split screen from frame one. Left: you in costume, drink in hand, 10:14 PM on screen. Right: same you at the pumpkin patch, kids running, 9:02 AM. No talking yet.', 'At 3 seconds cut to the bathroom mirror earlier that night: the patch goes on before the costume is finished, design facing the lens.', 'Get 1906 launched on Oct 1 with ''Off Duty on Friday. On duty for Saturday''s 7am pancakes'' and every ad in the set is climbing. Two clocks on screen is that idea with a costume on.', '[{"brand": "Get 1906", "what": "The two scenes with the time on screen: Friday night, then the 7am morning. Steal the hard cut.", "url": "https://app.tryatria.com/ad/m1859426501710827"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('62e02e798cf7b827', 'act_1033194534145987', '4942d9a1c63d1254', 0, 0, 2, 'live', 'Because moms deserve Halloween too', 'The kids get Halloween every year. This is the night mom and her friends take it back, and the bundle has a design for each of them.', 'A group of mom friends dressing up for their own Halloween night.', 'Halloween bundle (3 designs, 2 of each, 6 patches)', 'Group reaction', NULL, '["The kids had their Halloween. This one''s ours.", "Group chat said costumes are mandatory. And patches, apparently.", "Six patches, three designs, four moms. Somebody is fighting over Momster."]', '[{"label": "Open · 0 to 3s", "text": "Hands into the bundle, names to the lens, first line."}, {"label": "Middle", "text": "Patches go on before anyone pours. Everyone reads her name out loud. Argue over who is Resting Witch Face."}, {"label": "Close", "text": "Cheers shot with the patches on arms. End on the group laughing, not on the drinks."}]', 'Momster / Resting Witch Face / Here for the Boos', 'Say "six patches, three designs" out loud. Let the names get the laugh.', 'Film it alone, and don''t say a bundle price. Say to check the site.', NULL, 'Four hands reach into the open Halloween bundle at once. Patches come out, names up to the lens: Momster, Resting Witch Face, Here for the Boos.', 'Each friend reads her patch name out loud and reacts. By the third name they are arguing over who gets which.', 'dayguard''s number one ad is built on a ritual you can see: ''Koreans even cheers the sticks before their first shot.'' Four patches going on at once is our ritual, and the names are the joke.', '[{"brand": "dayguard", "what": "The group ritual before the first drink, made visible.", "url": "https://app.tryatria.com/ad/m27797344126635112"}, {"brand": "Waterboy", "what": "Two friends holding things up and reading them out. Steal the back-and-forth.", "url": "https://app.tryatria.com/ad/m1616399766694709"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('3213abfbb4c21db8', 'act_1033194534145987', '4942d9a1c63d1254', 0, 0, 3, 'live', 'He said he did not need one', 'Couples costume night is the one night you both go out, and you both still have to parent at 7.', 'Couples going to a costume party with kids at home.', 'Halloween bundle', 'Skit', NULL, '["Husband said he doesn''t need one. Watch this.", "Matching costumes. Only one of us wore a patch. Guess who''s making pancakes.", "We did a couples costume. We also both have a 7am wake-up call. One of us planned for it."]', '[{"label": "Open · 0 to 3s", "text": "Mirror, costumes, her patch on, his wave-off."}, {"label": "Middle", "text": "The morning: pancakes, kids, her moving fast. Him moving slow, holding a coffee, still in the hat."}, {"label": "Close", "text": "He holds his hand out for a patch for next time. She hands it over with a look. Pack on the counter."}]', 'He said he didn''t need one.', 'Keep it light. He is in on the joke.', 'Make the morning look like a sick day. He is slow, not suffering.', NULL, 'Matching costumes in the hallway mirror. She presses her patch on, then holds one out to him. He waves it off. Still no words.', 'Hard cut to 7:05 AM: she is flipping pancakes in half her costume makeup. He walks in slow. Keep it playful, never sick.', 'Waterboy''s rising skit this month runs on one joke carried all the way through. The joke here is on him, not on drinking, and the morning stays loud and funny.', '[{"brand": "Waterboy", "what": "One absurd premise, played straight to the end. Steal the commitment to the bit.", "url": "https://app.tryatria.com/ad/m1401112791381628"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('f48f5d242f1a051e', 'act_1033194534145987', '4942d9a1c63d1254', 0, 0, 4, 'live', 'Where the patch hides under the costume', 'People ask where it goes. Under a costume there are five good spots, and showing them is the whole video.', 'Anyone building a costume that is more than a t-shirt: witch, cat, cowgirl, the group theme.', 'Halloween bundle', 'Get ready with me', NULL, '["Where does the patch go under a witch costume? Here. Watch.", "Costume on. Patch on. You will not find it.", "Everyone asks where I put it. Shoulder, hip, or the one spot the dress hides."]', '[{"label": "Open · 0 to 3s", "text": "Hands first: patch pressed on, strap over it."}, {"label": "Middle", "text": "Finish the costume in fast cuts: lashes, hat, boots. Spin. \"Guess where.\""}, {"label": "Close", "text": "Strap down for the reveal, then out the door with your friends."}]', 'Shoulder. Hip. Under the strap. Pick one.', 'Make the patch a real step in getting ready, not an afterthought at the end.', 'Skip the reveal. People watch to see where it went.', NULL, 'Camera close on your hands pressing the patch onto your shoulder. Then the costume strap comes down over it. Gone.', 'At 3 seconds, "guess where it is" and a fast spin in the finished costume. Then the reveal: strap up, patch there.', 'The Good Patch''s rising ad opens on the inside of a wrist with the patch pressed on, camera close, before a word is said. The ritual is the hook; the costume is the reason to watch to the end.', '[{"brand": "The Good Patch", "what": "Patch pressed onto the wrist, camera close, first line after. Steal the hands-first open.", "url": "https://app.tryatria.com/ad/m1775730420219793"}, {"brand": "The Good Patch", "what": "The six-second peel, stick, go loop. Steal the pace.", "url": "https://app.tryatria.com/ad/m1472651414618482"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('23fb9ce5762b1ecd', 'act_1033194534145987', 'f00eb512856495df', 0, 0, 5, 'live', 'The Christmas card morning', 'The holiday party is Saturday night and the family card photo is Sunday at 9, and she planned for both.', 'Moms who booked the photographer and bought the matching pajamas.', 'Party Patch', 'Split screen', NULL, '["Holiday party Saturday. Christmas card photos Sunday at nine. I planned for this.", "You can see last year''s party in last year''s card. Not this year.", "Sequins at nine pm. Matching pajamas at nine am. Same woman."]', '[{"label": "Open · 0 to 3s", "text": "The split, both clocks."}, {"label": "Middle", "text": "Patch on under the sequins in the bathroom mirror. Then the party, two quick cuts."}, {"label": "Close", "text": "The card photo. Everyone smiling. Hold the real print up to the lens if you have it."}]', '9PM / 9AM', 'Use your real card shoot. Film it in November so it runs in December.', 'Show the old "tired" card or say you looked rough. Just show this one.', NULL, 'Left: sequins, 9:12 PM, a drink in hand. Right: matching pajamas, a photographer counting down, 9:04 AM. Both clocks on screen.', 'At 3 seconds "three, two" from the photographer, then the flash. Then back to the party: the patch going on under the sequins.', 'Get 1906 names the morning plan out loud: ''tomorrow''s workout, game, meeting, or morning plans are still happening.'' A named morning beats a vague one, and a photographer counting down is a morning you can see.', '[{"brand": "Get 1906", "what": "The named morning plan. Steal the specificity.", "url": "https://app.tryatria.com/ad/m28648022974882496"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('49d25e3d04d9e474', 'act_1033194534145987', 'f00eb512856495df', 0, 0, 6, 'live', 'Office party tonight, meeting at nine', 'The holiday party lands on a weeknight and the 9am meeting does not move.', 'Women going to a work holiday party on a Tuesday.', 'Party Patch', 'Get ready with me', NULL, '["Office party tonight. Meeting at nine. Both are happening.", "Get ready with me for the work party. On a Tuesday. With a nine am.", "Holiday party outfit check, and the one thing nobody at the office will see."]', '[{"label": "Open · 0 to 3s", "text": "Laptop shut, patch on, shoes out. No words until the patch is on."}, {"label": "Middle", "text": "The outfit swap, the party: dancing with coworkers, one drink in hand, 21+ only."}, {"label": "Close", "text": "Next morning on the video call, sharp, patch visible when you reach for the coffee."}]', 'PARTY: 7PM / MEETING: 9AM', 'Make the patch its own step in getting ready, right after the laptop closes.', 'Film coworkers who did not agree to be in it.', NULL, 'Your work laptop closing at 5:58 PM, then your hand pressing a patch on, then the party shoes coming out of the desk drawer.', 'Text at 3 seconds: "Meeting at 9 tomorrow." Then the outfit swap in three cuts.', 'ZBiotics is running ''Don''t let a great night out compromise a productive morning routine'' as a four-second clip. The weeknight version of that stake is a meeting, and that is her exact fear.', '[{"brand": "ZBiotics", "what": "The productive-morning stake stated in four seconds. Steal the brevity.", "url": "https://app.tryatria.com/ad/m1610793354114367"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('8e154c14e30c6cee', 'act_1033194534145987', 'f00eb512856495df', 0, 0, 7, 'live', 'The biggest Wednesday night of the year', 'Thanksgiving Eve is the hometown reunion, and Thanksgiving morning in mom''s kitchen starts early.', 'Women home for Thanksgiving meeting everyone from high school at the one bar in town.', 'Party Patch', 'Day in the life', NULL, '["Home for Thanksgiving. Everyone from high school is at the bar tonight. Mom needs me at seven.", "The biggest bar night of the year is a Wednesday. Patch in the car. Let''s go.", "Thanksgiving Eve rules: patch first, then hug everyone you went to school with."]', '[{"label": "Open · 0 to 3s", "text": "Driveway, dome light, patch on, the bar name."}, {"label": "Middle", "text": "Hugs at the bar, the group photo, one drink in hand. Keep it warm, not wild."}, {"label": "Close", "text": "Thanksgiving morning in the kitchen with mom, peeling something, fully present. Pack on the windowsill."}]', 'THANKSGIVING EVE / THANKSGIVING, 6:40AM', 'Film the real reunion, with everyone asked first.', 'Shots, rounds, anyone who looks drunk. It is a hug night.', NULL, 'Patch going on in the car in your parents'' driveway, dome light on, the bar name on your phone screen.', 'At 4 seconds the first hug at the bar door, someone you have not seen in ten years. Then the clock: 6:40 AM, the turkey.', 'Waterboy''s rising mom video opens with a real trip (Disneyland, the beach, the red-eye) and the product arrives late, as the thing that rides along. A hometown Wednesday is that story for us.', '[{"brand": "Waterboy", "what": "A real day told fast, product riding along, arriving once the story has earned it.", "url": "https://app.tryatria.com/ad/m1386099517035759"}, {"brand": "dayguard", "what": "''Drink Tonight. Feel Better Tomorrow.'' has run 140 days. Steal the one-breath promise, keep our words.", "url": "https://app.tryatria.com/ad/m1720332875988351"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('048d791c7698a434', 'act_1033194534145987', 'f00eb512856495df', 0, 0, 8, 'live', 'Count the nights between now and New Year''s', 'She counted the parties on her calendar from now to January 1 and bought one patch for each of them.', 'The planner who buys ahead, and anyone who has run out the night of the party.', 'Bundles', 'Voiceover', NULL, '["I counted my nights out between now and New Year''s. Nine. So I bought nine.", "Every party on this calendar gets a patch. Every single one.", "Friendsgiving, two office parties, the girls'' dinner, New Year''s. I did the math."]', '[{"label": "Open · 0 to 3s", "text": "The circling, the count climbing."}, {"label": "Middle", "text": "Patches laid on the circles, one each. Then one going on before the first of them."}, {"label": "Close", "text": "Say the bundle offer exactly as the site shows it the day you post, then the pack into the purse."}]', 'Nights out until Jan 1: 9. Patches: 9.', 'Use your real calendar and your real number.', 'Make up a discount or a price. Only the offer that is live on the site the day you post.', NULL, 'A wall calendar, your hand circling every night out in red marker, fast: Friendsgiving, office party, girls dinner, NYE.', 'The count on screen climbs with each circle. At 5 seconds you tip the bundle out and lay one patch on each circle.', 'Our two best statics are a bundle message and ''before the weekend''. ZBiotics'' four-second ''stocked bar cart'' ad is the same idea on video: being prepared is the pitch, and a count is the rehook.', '[{"brand": "ZBiotics", "what": "''Being prepared is the key to a better tomorrow. Ensure your bar cart is always stocked.'' Steal the stock-up frame.", "url": "https://app.tryatria.com/ad/m28182952651327819"}, {"brand": "Waterboy", "what": "A number that keeps changing holds people. Steal the count.", "url": "https://app.tryatria.com/ad/m1616399766694709"}]');
