INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('52447976cd3280e0', 'act_1033194534145987', 'f00eb512856495df', 0, 0, 9, 'live', 'I''m the friend with the patches', 'Every group has the one who brings the thing. At the girls'' Christmas dinner she is the one with the patches in her purse.', 'The mom friend of the mom friends, at the girls'' Christmas dinner or the white elephant.', 'Party Patch', 'Group reaction', NULL, '["Every group has one. I''m the one with the patches.", "You bring the Advil. I bring these. Christmas dinner, let''s go.", "My white elephant gift got stolen twice. It was a patch pack."]', '[{"label": "Open · 0 to 3s", "text": "The purse, the pack, the faces."}, {"label": "Middle", "text": "The handout, one reason each. Patches on arms before the first glass is lifted."}, {"label": "Close", "text": "Four patches on, the cheers, the laugh. Then her, to camera: \"Somebody has to be the planner.\""}]', 'The planner friend.', 'Let the friends react for real. Ask them first.', 'Film it alone at a table. This one needs the faces.', NULL, 'Her purse opens on the restaurant table, a pack comes out, and the camera catches four faces lighting up.', 'Handing them out, one line per friend: "you have the 6am flight, you have the toddler, you have the in-laws."', 'Waterboy''s rising ad reads a review out loud: ''for a recent bachelorette party I included Waterboy in hangover kits I made.'' The planner who brings them for everyone is a real customer, and Get 1906 sells ''control freak'' as a compliment.', '[{"brand": "Waterboy", "what": "The named review about kits for the whole group. Steal the planner as the hero.", "url": "https://app.tryatria.com/ad/m1541318970835567"}, {"brand": "Get 1906", "what": "''Happy hour for control freaks.'' Steal the proud self-description.", "url": "https://app.tryatria.com/ad/m1061582806703549"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '2885e3bc07ed9671', 'act_1033194534145987', '52447976cd3280e0', 'meta', '120249488847230266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120249488847230266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='52447976cd3280e0' AND ad_id='120249488847230266');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('5fff9c99c6d8a4d9', 'act_1033194534145987', 'f00eb512856495df', 0, 0, 10, 'live', 'Big night, bigger tomorrow', 'New Year''s Eve is the biggest night of the year, and January 1 is day one of whatever she promised herself.', 'Women going out for New Year''s Eve with a plan for the morning: the hike, the run, the pancakes.', 'Party Patch', 'Get ready with me', NULL, '["Big night. Bigger tomorrow. My resolutions start at nine am and I mean it this time.", "New Year''s Eve get ready with me. The patch goes on first. Then the dress.", "Last thing I put on before New Year''s Eve is the thing that gets me to January first."]', '[{"label": "Open · 0 to 3s", "text": "Dress on the hanger, patch on, the clock."}, {"label": "Middle", "text": "Lashes, hair, the dress over the patch, the door. One midnight clip, one drink, 21+ only."}, {"label": "Close", "text": "January 1: the hike, the run, the pancakes with the kids. Pack on the counter."}]', 'DEC 31, 7:48PM / JAN 1, 9:00AM', 'Name your real January 1 plan on screen.', 'Show the countdown crowd drinking. One glass at midnight is plenty.', NULL, 'The sequin dress on the hanger, your hand pressing the patch on your hip before it goes over, the clock reading 7:48 PM.', 'Text at 3 seconds: "Resolutions start at 9am." Then the glam in fast cuts.', 'ZBiotics'' bachelorette ad lands on ''I wanted to be present for it all'' with Pilates the next morning. January 1 is the most planned morning of the year, so the stake needs no explaining.', '[{"brand": "ZBiotics", "what": "''We also had Pilates planned, so I wanted to be present for it all.'' Steal the named next-morning plan.", "url": "https://app.tryatria.com/ad/m1025728377183837"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('6f7ea9949328d528', 'act_1033194534145987', '0c8750fe8a644523', 1, 1, 11, 'live', 'Off duty, on duty', 'She gets one night off a week, and at 7am Saturday she is back on. The patch is how both happen.', 'Moms with kids under 10.', 'Party Patch', 'Day in the life', NULL, '["Off duty Friday. On duty for seven am pancakes. You know how this ends.", "I get one night off a week. I am not spending Saturday on the couch.", "Mom''s off duty. For about six hours. Then pancakes."]', '[{"label": "Open · 0 to 3s", "text": "The two-time cut, OFF DUTY then ON DUTY."}, {"label": "Middle", "text": "The mirror: patch on, design to the lens, keys in hand."}, {"label": "Close", "text": "Pancake flipped, kid cheering, syrup everywhere, patch visible on your wrist."}]', 'OFF DUTY 8PM / ON DUTY 7AM', 'Make the morning loud and real: kids, dog, syrup.', 'Show the morning from bed. Not even for the joke.', NULL, 'Text OFF DUTY over you laughing at a bar with friends, 8:14 PM on screen. Hard cut to ON DUTY, 7:02 AM, flipping pancakes with a kid on the counter. No talking yet.', 'At 4 seconds flash back to the bathroom mirror: the patch goes on before you leave. Then back to the pancakes, louder.', 'Get 1906 launched this exact mom on Oct 1 (''Off Duty on Friday. On duty for Saturday''s 7am pancakes'') and every ad in the set is rising. The domestic detail is what makes it land: pancakes, not ''responsibilities''.', '[{"brand": "Get 1906", "what": "The two scenes and the creator''s line ''I can get up in the morning with the kids and feel like myself''. Steal the pancakes.", "url": "https://app.tryatria.com/ad/m1859426501710827"}, {"brand": "Get 1906", "what": "''Tomorrow''s workout, game, meeting, or morning plans are still happening.'' Steal the named morning.", "url": "https://app.tryatria.com/ad/m28648022974882496"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e63950b0ab52c8a6', 'act_1033194534145987', '0c8750fe8a644523', 1, 2, 12, 'live', 'I tried to hire someone for the morning', 'Parents actually book sitters for the morning after a night out. She priced it, then looked at the patch.', 'Parents of early risers, 30 to 45.', 'Party Patch', 'Skit', NULL, '["I called a sitter for the morning after girls night. A hundred and twenty dollars. Or.", "Tried to outsource my Saturday morning. Here''s what that costs.", "There is a cheaper option than a morning babysitter. It''s on my arm."]', '[{"label": "Open · 0 to 3s", "text": "The call, straight-faced."}, {"label": "Middle", "text": "The quote on screen, the look at the pack, the patch going on that night before you leave."}, {"label": "Close", "text": "Saturday 7am, you at soccer yourself, coffee in hand, patch on. \"Kept the hundred and twenty.\""}]', 'Morning sitter: $120. Patch: see the site.', 'Use real sitter rates for your city, and say the patch price from the site the day you post.', 'Imply the kids were ever left alone.', NULL, 'You on the phone at the kitchen counter, deadly serious: "Hi. Do you do 7am soccer? Saturday? After a girls night?"', 'The quote comes back as text on screen: Morning sitter: $120. You look down at the patch pack beside the phone. Long pause.', 'Waterboy''s rising 82-second skit is ''can I rent a waterboy for the day'', played straight. The sitter premise is absurd and true: parents really do book morning babysitters, which is why the price comparison sells without a claim.', '[{"brand": "Waterboy", "what": "The rent-a-person premise, played straight to the end. Steal the deadpan.", "url": "https://app.tryatria.com/ad/m1401112791381628"}, {"brand": "Scary Mommy", "what": "The \"hangover babysitter\" is a real thing parents book, and two thirds of parents plan childcare for the day after. Steal the true premise.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'a4e4547735b49d1b', 'act_1033194534145987', 'e63950b0ab52c8a6', 'meta', '120249211680840266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120249211680840266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='e63950b0ab52c8a6' AND ad_id='120249211680840266');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('d3e6cf29c143a0fa', 'act_1033194534145987', '0c8750fe8a644523', 0, 0, 13, 'live', 'Your calendar doesn''t care what you did last night', 'Tomorrow is already booked, so she wears the patch tonight and still shows up on the sideline.', 'The mom whose Saturday starts on a soccer sideline at 8.', 'Party Patch', 'Split screen', NULL, '["Your calendar doesn''t care what you did last night. Mine says soccer at eight.", "Nine forty-seven pm, margaritas. Eight oh three am, sideline. Both me.", "Girls night was last night. Soccer is at eight. I''m fine, and here''s why."]', '[{"label": "Open · 0 to 3s", "text": "The split, both clocks."}, {"label": "Middle", "text": "Dinner: patch on, then the drink arrives. Two quick laughs with the girls."}, {"label": "Close", "text": "The sideline: you cheer for your kid, loud. Pack on the chair arm."}]', 'TONIGHT: girls night / TOMORROW: 8AM soccer', 'Keep her looking good in both halves. The clock does the work.', 'Show her tired or hurting on the sideline. The point is she is fine.', NULL, 'Split screen. Left: 9:47 PM, margaritas with the girls, mid-laugh. Right: 8:03 AM, same you on the sideline in a camp chair, big coffee. Both times on screen before anyone talks.', 'At 3 seconds, back to dinner: the patch goes on before the first drink arrives, close enough to read.', 'Waterboy says it in one breath: ''tonight''s gonna be amazing, tomorrow is gonna suck unless''. The stake is on screen in under three seconds and she fills in her own tomorrow. dayguard has run its version for 140 days.', '[{"brand": "Waterboy", "what": "The tonight-tomorrow line in one breath. Steal the speed.", "url": "https://app.tryatria.com/ad/m1541318970835567"}, {"brand": "dayguard", "what": "''Drink Tonight. Feel Better Tomorrow.'' in its 140-day ad. Steal the two-word stakes, keep our words.", "url": "https://app.tryatria.com/ad/m1720332875988351"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e888bcace3653263', 'act_1033194534145987', '0c8750fe8a644523', 0, 0, 14, 'live', 'If you have kids, watch this', 'Kids wake up at six whether you went out or not. Say who this is for in the first line and let everyone else scroll.', 'Parents, said straight to them.', 'Party Patch', 'Talking to camera', NULL, '["If you drink wine and you have kids, this one''s for you.", "Kids do not care that you went out last night. Mine were up at six.", "My six am alarm is three feet tall and does not have a snooze button."]', '[{"label": "Open · 0 to 3s", "text": "The 6:45 kitchen, the text, the milk."}, {"label": "Middle", "text": "Last night: patch on in the car or the mirror, then the one drink, then home."}, {"label": "Close", "text": "Back to the kitchen: cereal poured, kid fed, you awake. Patch visible on your wrist as you reach for the coffee."}]', 'IF YOU HAVE KIDS.', 'Kids only with consent, or show the empty bowls and the cartoons.', 'Show kids anywhere near a drink.', NULL, 'Text IF YOU HAVE KIDS over a kitchen at 6:45 AM: cereal already out, cartoons on, you pouring milk.', 'At 3 seconds: "because they wake up at six whether you went out or not." Then flash to last night, the patch going on.', 'The Cheers founder opens his rank-4 ad with ''If you drink alcohol and you have kids and you have parents and grandparents, then you need to know about this.'' Self-selection in line one is why a two-minute talking head still works for him.', '[{"brand": "The Cheers CEO", "what": "The persona call-out in the first sentence. Steal ''if you have kids'' and the straight delivery.", "url": "https://app.tryatria.com/ad/m1367112002210185"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('6f185435fe16e4fa', 'act_1033194534145987', '0c8750fe8a644523', 0, 0, 15, 'live', 'Stop losing Saturdays', 'Saturday is the only day that is hers. She counted the ones she gave away last year and stopped.', 'Women 35 to 50 whose Saturday is the only day that belongs to them.', 'Party Patch', 'Voiceover', NULL, '["I counted the Saturdays I lost last year. I''m not doing that again.", "Saturday is the only day that''s mine. I stopped giving it away.", "Eleven Saturdays left this year. I want every one of them."]', '[{"label": "Open · 0 to 3s", "text": "The crossing out, fast."}, {"label": "Middle", "text": "Friday night: patch on before the drink, the girls, one laugh."}, {"label": "Close", "text": "A Saturday: farmers market, soccer, the hike. Same woman, moving. Pack in the tote."}]', 'Saturdays left this year: 11.', 'Use the real number of Saturdays left on the day you film.', 'Show the lost Saturday. We never show the bad morning.', NULL, 'A wall calendar, a red marker crossing out Saturdays one after another, fast, no words.', 'The pen stops at the next Saturday and draws a little patch on it instead. Then the real number of Saturdays left this year lands on screen.', 'dayguard''s rank-2 ad is ''Stop Losing Your Mornings'' and ''this is your precious weekend, but you''re wasting it''. Wynk sells ''zero days wasted''. We take the count and leave the hungover picture out.', '[{"brand": "dayguard", "what": "''Stop Losing Your Mornings'' and ''Win-back Your Weekends''. Steal the loss, not the couch.", "url": "https://app.tryatria.com/ad/m1533442648531847"}, {"brand": "Wynk Seltzer", "what": "''Zero days wasted.'' Steal the count.", "url": "https://app.tryatria.com/ad/m1483981077081289"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'c16512c3ce4d04d3', 'act_1033194534145987', '6f185435fe16e4fa', 'meta', '120246582639020266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120246582639020266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='6f185435fe16e4fa' AND ad_id='120246582639020266');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('0b803632fb2ccb22', 'act_1033194534145987', '0c8750fe8a644523', 0, 0, 16, 'live', 'Happy hour for control freaks', 'She plans everything, including how she feels tomorrow. The patch lives in the planner.', 'The planner mom with the color-coded calendar.', 'Party Patch', 'Screen record', NULL, '["Happy hour for control freaks. That''s me. Hi.", "I plan everything. Including tomorrow morning.", "I''m the friend with the itinerary and the patches. Somebody has to be."]', '[{"label": "Open · 0 to 3s", "text": "The calendar, Friday then Saturday, the tap."}, {"label": "Middle", "text": "The night, patch visible on the arm, one drink, the girls."}, {"label": "Close", "text": "Saturday''s box gets ticked in the planner. Then the soccer field."}]', 'Planned: the night. Planned: the morning.', 'Show your real calendar. Hide anything private first.', 'Make her look stressed. Control is the joke, not the problem.', NULL, 'Screen record of your phone calendar: a finger taps Friday GIRLS NIGHT, then Saturday SOCCER 8AM. Or the paper planner, same thing.', 'At 3 seconds you pull a patch out of the planner pocket (or the phone case) and hold it to the lens.', 'Get 1906''s rank-4 ad is ''Happy hour for control freaks'' and ZBiotics'' whole September set is ''built for those who plan ahead''. Both sell a self-description the viewer is proud of. Our best static says ''before the weekend'': same buyer.', '[{"brand": "Get 1906", "what": "''Happy hour for control freaks. Any drink, same feeling, every single time.'' Steal the proud label.", "url": "https://app.tryatria.com/ad/m1061582806703549"}, {"brand": "ZBiotics", "what": "''Built for those who plan ahead.'' Steal the planner.", "url": "https://app.tryatria.com/ad/m2194257071137920"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '4584d4c6b5cae79a', 'act_1033194534145987', '0b803632fb2ccb22', 'meta', '120249488847230266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120249488847230266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='0b803632fb2ccb22' AND ad_id='120249488847230266');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('9980fc4672fd4732', 'act_1033194534145987', '0c8750fe8a644523', 0, 0, 17, 'live', 'Day two is the whole point', 'Night one is dinner. Day two is the boat, the hike, the winery. She is not missing day two.', 'Women on a girls trip, 35 to 50.', 'Party Patch', 'Day in the life', NULL, '["Day one is dinner. Day two is the boat. I am not missing the boat.", "We booked a nine am hike after a tequila night. Watch this.", "Girls trip rule: nobody skips day two. Nobody."]', '[{"label": "Open · 0 to 3s", "text": "The itinerary, the finger."}, {"label": "Middle", "text": "Dinner: patches going on around the table, visible, before the first round."}, {"label": "Close", "text": "The boat, the hike, the winery. All four of you there. Pack in the beach bag."}]', 'DAY 1: dinner. DAY 2: the boat.', 'Show the patch on night one, on camera.', 'Film anyone looking rough on day two. Everyone made the boat.', NULL, 'The trip itinerary on paper or a Notes screenshot, finger running down it: Day 1 dinner, bar. Day 2 boat, 9AM.', 'Night footage cut hard to the 9am boat: hair up, coffee, sunglasses on your head, not your face.', 'ZBiotics'' rising bachelorette ad is built on one line: ''we also had Pilates and a full day of activities planned, so I wanted to be present for it all.'' Day two is the stake nobody else in the category is filming.', '[{"brand": "ZBiotics", "what": "''I wanted to be present for it all.'' Steal the next-day plan as the reason.", "url": "https://app.tryatria.com/ad/m1025728377183837"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('79035df58c0721bb', 'act_1033194534145987', '9214992e83576385', 1, 3, 18, 'live', 'I''m 44 and two glasses is a two-day event', 'Say her age out loud. What used to be a Tuesday now costs her a weekend, and she is done pretending otherwise.', 'Women 40 to 50. The viewer who nods before you finish the sentence.', 'Party Patch', 'Talking to camera', NULL, '["I''m forty-four. Two glasses of wine used to be a Tuesday. Now it''s a two-day event.", "Where did my tolerance go? Asking for every woman at book club.", "Nobody told me that at forty, one drink costs a whole morning. So. Here''s what I do."]', '[{"label": "Open · 0 to 3s", "text": "Fingers, glasses, calendar."}, {"label": "Middle", "text": "Patch on before the drink, mid-sentence, like it is normal."}, {"label": "Close", "text": "Sunday morning with the kids or the dog, pack on the counter. \"Two glasses. Two days. Not anymore.\""}]', '2 glasses. 2 days. Not anymore.', 'Say your real age.', 'Say it stops anything. "For a better next day." That is the line.', NULL, 'Two fingers up to the lens. Then two wine glasses. Then a calendar with Saturday AND Sunday crossed out. Three cuts, two seconds.', 'At 4 seconds: "so here''s what I do now", and the patch goes on while you keep talking.', 'The Good Patch''s rising ad opens ''40+ and feeling like your energy isn''t what it used to be?'' and Cheers built a company on ''after the age of 30, even responsible drinking makes you feel less than 100% the next day''. Nobody on our page says an age out loud yet.', '[{"brand": "The Good Patch", "what": "The ''40+'' opener. Steal the age in the first line.", "url": "https://app.tryatria.com/ad/m1775730420219793"}, {"brand": "The Cheers CEO", "what": "''After the age of 30, even responsible drinking makes you feel less than 100%.'' Steal the honesty about age.", "url": "https://app.tryatria.com/ad/m1367112002210185"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('a4aa60d7dea8d687', 'act_1033194534145987', '9214992e83576385', 0, 0, 19, 'live', 'I drink less now. That''s exactly why.', 'She is not a wine mom. She drinks once a month, and that is exactly why one night costs her.', 'The sober-curious mom who still says yes to girls night.', 'Party Patch', 'Talking to camera', NULL, '["I drink way less than I used to. So when I do, it hits harder.", "Two drinks a month. Both of them cost me a morning. Not anymore.", "I''m not a wine mom. I''m a once-a-month mom. It still wrecks me, so."]', '[{"label": "Open · 0 to 3s", "text": "The two pours, side by side."}, {"label": "Middle", "text": "Patch on. The one glass. The friends."}, {"label": "Close", "text": "The morning, moving: the walk, the kids, the market. Pack visible."}]', 'Less often. Hits harder.', 'Keep it light and proud. She is not confessing.', 'Lecture anyone, and never "mommy needs wine".', NULL, 'Pouring one glass of wine and one sparkling water side by side. Your hands, the counter, no face yet.', 'At 3 seconds: "and the one glass hits harder than it used to." Then the patch comes out of the drawer.', 'Get 1906''s rising launch ad is a mom who ''never thought I would be the person to turn down my Friday night glass of wine''. Drinking less is the mainstream now, and the brands winning say so instead of joking about wine.', '[{"brand": "Get 1906", "what": "The creator who turned down the Friday glass of wine. Steal the anti-wine-mom stance.", "url": "https://app.tryatria.com/ad/m1859426501710827"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('3301e1c5e968c5ab', 'act_1033194534145987', '9214992e83576385', 0, 0, 20, 'live', 'I''m 38 and I just read what''s in these', 'Flip the patch pack and the powder stick over and read the backs. Facts only, and the facts are on our side.', 'The label reader, 35 to 50.', 'Party Patch', 'Label read', NULL, '["I''m thirty-eight and I just read what''s in the stuff I take after a night out.", "Powder stick versus patch. Read the back with me.", "I''m not a scientist. I can read a label. Let''s go."]', '[{"label": "Open · 0 to 3s", "text": "The double flip."}, {"label": "Middle", "text": "Pointing at lines on both, reading only what is printed. Pack facts on screen."}, {"label": "Close", "text": "The patch goes on. \"Scent-free, zero calories, nothing to mix. That one''s mine.\""}]', 'Scent-free. Zero calories. Water resistant. Nothing to mix.', 'Read only what is printed on the Party Patch pack.', 'Say it works better than anything. Compare facts, never results.', NULL, 'A patch pack and a powder stick on the counter, both flipped to the back at the same time by one hand.', 'A finger runs down the panel, stops, "wait." Then the pack facts land on screen one at a time: scent-free, zero calories, water resistant, nothing to mix.', 'Waterboy''s reused label ad opens ''i''m 35 years old and i just found out what''s in these'' and its bartender does the math on camera. Age plus ''just found out'' is a curiosity gap, and words on screen give the eye a job.', '[{"brand": "Waterboy", "what": "''I''m 35 and I just found out what''s in these.'' Steal the age plus the flip.", "url": "https://app.tryatria.com/ad/m3128643533989877"}, {"brand": "Waterboy", "what": "''Check the label.'' Steal the finger running down the panel.", "url": "https://app.tryatria.com/ad/m961104253707387"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '6c1c8026766686f6', 'act_1033194534145987', '3301e1c5e968c5ab', 'meta', '120243115360050266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120243115360050266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='3301e1c5e968c5ab' AND ad_id='120243115360050266');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('1ef02b8b1e8d463d', 'act_1033194534145987', '9214992e83576385', 0, 0, 21, 'live', 'I did everything right', 'Water between drinks, dinner first, home by eleven, still rough the next day. So now she adds this.', 'The responsible drinker who follows every rule and still loses the morning.', 'Party Patch', 'Voiceover', NULL, '["Water between every drink. Dinner. Home by eleven. Still rough. So I added this.", "I did everything the internet said. Then I added one more thing.", "The water trick is not enough for me anymore. Here''s the extra step."]', '[{"label": "Open · 0 to 3s", "text": "Water next to wine, four times, fast."}, {"label": "Middle", "text": "Patch on before the first glass, the dinner, home early."}, {"label": "Close", "text": "The morning, moving. \"Water. Dinner. Early night. And this.\""}]', 'Water. Dinner. Early night. And this.', 'Say "for a better next day" and stop there.', 'Explain why water was not enough. No mechanism, no claim.', NULL, 'A water glass set down next to a wine glass. Four quick cuts, four tables, same move.', 'At 4 seconds: "and I still felt rough. So now I add this." The patch, on, mid-sentence.', 'DrinkAid opens ''You''ve been told to drink water. You did. You still felt terrible.'' The ''I did it right'' setup is a real buyer''s story. We keep the setup and leave out the mechanism.', '[{"brand": "DrinkAid", "what": "''You''ve been told to drink water. You did. You still felt terrible.'' Steal the setup, not the science.", "url": "https://app.tryatria.com/ad/m2792860367739408"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('c8cc466f3747cfa9', 'act_1033194534145987', '8d23caa34d96cec7', 1, 4, 22, 'live', 'The pile vs the patch', 'Her friend''s next-day routine is a whole pharmacy. Hers is one patch. Nobody has to claim anything.', 'Two friends, 30 to 50, getting ready for a night out.', 'Party Patch', 'Two-person trade', NULL, '["This is what she packs for a girls weekend. This is what I pack.", "Show me your morning-after routine. Okay. Here''s mine.", "She brought a pharmacy. I brought a patch."]', '[{"label": "Open · 0 to 3s", "text": "The pile and the patch, side by side, on the counter."}, {"label": "Middle", "text": "She holds up each item and names it. You answer \"patch\" each time. Cuts get faster."}, {"label": "Close", "text": "Both at the door, your patch on your arm, hers still packing. \"What did all that cost?\" Say the patch price from the site."}]', 'HER: Pedialyte. Advil. 3 bananas. ME: one patch.', 'Every line under two seconds. End on the price from the site the day you post.', 'Say the patch replaces water or food. "For a better next day."', NULL, 'A kitchen island covered in Pedialyte, bananas, a bottle of Advil, a powder stick, a gallon of water. One hand sets ONE patch down beside the pile.', 'The trade starts at 2 seconds and speeds up: she names an item, you say "patch". Every time. At 8 seconds she asks what it all cost.', 'Waterboy''s two rising partner ads this month are this exact trade: the pile, the one stick, and ''that must have cost a fortune / it''s $2 a stick'' as the ending. It is funny with the sound off and it needs no claims.', '[{"brand": "Waterboy", "what": "The trade and the price reveal at the end. Steal the rhythm.", "url": "https://app.tryatria.com/ad/m1616399766694709"}, {"brand": "Waterboy", "what": "Same shape, rising since Sept 28. Steal the speed-up.", "url": "https://app.tryatria.com/ad/m1058963726969933"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('18ffdea0e04e5627', 'act_1033194534145987', '8d23caa34d96cec7', 1, 5, 23, 'live', 'Not a cure', 'Nobody''s patch is magic. Say so first, then say what it is actually for. The honesty is the hook.', 'Any woman 30 to 50, filmed anywhere but a couch.', 'Party Patch', 'Talking to camera', NULL, '["This is not a hangover cure. Let me tell you what it is.", "I''m not going to tell you this fixes a tequila night. It doesn''t. Here''s what it does.", "Nobody''s patch is magic. Here''s what mine is for."]', '[{"label": "Open · 0 to 3s", "text": "Pack up, head shake, then the line."}, {"label": "Middle", "text": "Patch on before the night, where we can see it. The Uber, the door, the friends."}, {"label": "Close", "text": "Tomorrow morning: up and doing the thing, pack in frame. \"For a better next day. That''s it.\""}]', 'Not a cure. Just a better next day.', 'Say "for a better next day" out loud, in your own words.', 'List ingredients or explain how it works. Not a word of science.', NULL, 'Hold the pack up to the lens and shake your head no before you say a word.', 'At 3 seconds the "but": cut to the patch going on in the back of the Uber, then a 7am clip of you doing the thing.', 'Waterboy''s rising 11-second ad is hooked on ''Waterboy is not a cure for your hangover'', and its copy says ''Again, not a cure.'' The contradiction in the first second breaks the ad pattern, and it is our compliance line said as a hook.', '[{"brand": "Waterboy", "what": "''Waterboy is not a cure for your hangover.'' Steal the first-second contradiction.", "url": "https://app.tryatria.com/ad/m2432062563971120"}, {"brand": "The Cheers CEO", "what": "''Plot twist: I make money telling people they SHOULDN''T drink.'' Steal the honesty as a hook.", "url": "https://app.tryatria.com/ad/m1013483928135810"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('907f4de4338e76b9', 'act_1033194534145987', '8d23caa34d96cec7', 0, 0, 24, 'live', 'What am I?', 'The patch answers yes-or-no questions until you guess it. Every answer is a pack fact and the reveal is the name.', 'Any creator with a sense of humor and a free hand.', 'Party Patch', 'Skit', NULL, '["Do I smell? No. Do I fall off in the pool? No. Do I have calories? No. What am I?", "Twenty questions with the thing on my arm. Go.", "Guess what I am. You get three questions."]', '[{"label": "Open · 0 to 3s", "text": "Puppet patch, the voice."}, {"label": "Middle", "text": "The run of questions, one-word answers, cuts getting quicker. A friend sniffs your arm and guesses wrong."}, {"label": "Close", "text": "It goes on your arm. \"I''m Party Patch.\" Then the door."}]', 'Smell? No. Pool? No. Calories? No.', 'One-word answers only. Stick to pack facts: scent-free, zero calories, water resistant.', 'Ever answer "cure". And say water resistant, not waterproof.', NULL, 'The patch held up to the lens like a puppet. Your voice drops for it.', 'The yes/no run, faster each time: "Do I smell? No. Do I fall off in the pool? No. Calories? No." A friend sniffs your arm and guesses wrong.', 'Waterboy''s October partner ad has the product interview itself (''Do I help with nausea? Yeah. What am I? You''re Waterboy''). A yes/no run is a rhythm, the reveal is the brand name, and our old sniff test lives inside it.', '[{"brand": "Waterboy", "what": "The self-interview. Steal the yes/no run and the reveal.", "url": "https://app.tryatria.com/ad/m2202458353636113"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '2c1653127d3d3046', 'act_1033194534145987', '907f4de4338e76b9', 'meta', '120243115360050266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120243115360050266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='907f4de4338e76b9' AND ad_id='120243115360050266');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('0ca84c697596a497', 'act_1033194534145987', '8d23caa34d96cec7', 0, 0, 25, 'live', 'Peel. Stick. Door.', 'The last thing she does before she leaves takes three seconds. Five destinations, five loops, one afternoon.', 'Anyone. Film five in one go.', 'Party Patch', 'Six-second loop', NULL, '["Three seconds at the door. That''s it.", "Last thing before I leave. Every time.", "Peel. Stick. Go."]', '[{"label": "Open · 0 to 3s", "text": "Door, handle, press."}, {"label": "Middle", "text": "The press, close. Design to the lens for one beat."}, {"label": "Close", "text": "Door opens, she is gone. Text with the destination, one word."}]', 'BOOK CLUB / WEDDING / BUNCO / GIRLS TRIP / OFFICE PARTY (one per loop)', 'Film five destinations in one afternoon. Same door, different text.', 'Add a voiceover. The loop is the point.', NULL, 'The front door, your hand on the handle, the other hand pressing the patch on. No face needed.', 'The text swaps to where she is going: book club. Wedding. Bunco. Girls trip. Office party.', 'The Good Patch''s rank-1 ad for 80 days is a 6.8-second peel, stick, go loop. The action is the demo and it plays three times before a talking head finishes saying hello.', '[{"brand": "The Good Patch", "what": "The 6.8-second peel, stick, go loop at rank 1. Steal the loop.", "url": "https://app.tryatria.com/ad/m1472651414618482"}, {"brand": "ZBiotics", "what": "A 3.9-second ad. Steal the nerve to be short.", "url": "https://app.tryatria.com/ad/m28182952651327819"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('69e03ed798b77dac', 'act_1033194534145987', '8d23caa34d96cec7', 0, 0, 26, 'live', 'Sunglasses inside', 'At brunch, three friends wear sunglasses indoors and one does not. No one has to say anything.', 'Any friend group. No talking needed.', 'Party Patch', 'Trend', NULL, '["POV: you''re the only one at brunch not wearing sunglasses inside.", "Guess which one of us wore a patch last night.", "Same night. Different mornings. Pass the menu."]', '[{"label": "Open · 0 to 3s", "text": "The table, the three pairs, the push-in."}, {"label": "Middle", "text": "The sleeve, the patch, a tiny smile."}, {"label": "Close", "text": "She orders for everyone. The others nod slowly."}]', 'Same night. Different mornings.', 'Trending sound, under ten seconds, film it at a real brunch.', 'Make the friends look sick. Sunglasses is as far as it goes.', 'Any trending brunch or "POV" sound.', 'A brunch table, three pairs of sunglasses on, the camera pushes in on the one bare face.', 'At 3 seconds she lifts her sleeve: the patch. Then she takes everyone''s order.', 'Waterboy''s rising 6.5-second partner clip is one visual joke and one line. The sunglasses are the entire joke here, and the friends look fine, just quiet.', '[{"brand": "Waterboy", "what": "A 6.5-second one-visual joke (''if I''m gonna suffer I''d at least like to be hydrated about it''). Steal the brevity.", "url": "https://app.tryatria.com/ad/m1759281172163994"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('6155379515373f65', 'act_1033194534145987', '8d23caa34d96cec7', 0, 0, 27, 'live', 'Reading reviews until I find one that is me', 'Scroll the Party Patch reviews on the site until one of them is her, and say so.', 'Any creator. A phone and a face.', 'Party Patch', 'Screen record', NULL, '["Reading Party Patch reviews until I find one that''s me.", "Reading your reviews until one of them is my exact life.", "Okay this review is literally me. Read it with me."]', '[{"label": "Open · 0 to 3s", "text": "The scroll, the stop, the read."}, {"label": "Middle", "text": "Three reviews, three reactions, the exact words on screen."}, {"label": "Close", "text": "The pack to the lens. \"Ordering the bundle.\" Say the offer from the site, if there is one."}]', 'The review text, exactly as it reads on the site.', 'Only reviews that are live on partypatch.com, word for word, with the words on screen.', 'Read anything that sounds medical. Skip any review that says cured, prevented or stopped.', NULL, 'Screen record of partypatch.com reviews scrolling, your thumb stops on one, you read it out loud.', 'Each review gets a reaction and a "same". The third one gets a story from your own life.', 'Waterboy''s rising ad reads a review out loud with the name: ''Cali D said for a recent bachelorette party I included Waterboy in hangover kits I made.'' A review in a customer''s words supplies the scene, and nobody has to make a claim.', '[{"brand": "Waterboy", "what": "The named review read in the creator''s own voice. Steal the ''same''.", "url": "https://app.tryatria.com/ad/m1541318970835567"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('cc51909f04e57097', 'act_1033194534145987', '8d23caa34d96cec7', 0, 0, 28, 'live', 'The hot tub test', 'Patches are famous for falling off wet. Film this one staying on through the hot tub on the girls trip, with a timer.', 'Girls-trip creators with a pool or a hot tub.', 'Party Patch', 'Test', NULL, '["Every patch I''ve tried falls off in the pool. Testing this one.", "Hot tub test. Girls trip edition. Timer''s on.", "Water resistant, they said. Let''s see."]', '[{"label": "Open · 0 to 3s", "text": "Arm in, timer on."}, {"label": "Middle", "text": "The jumps, the arm out each time, a friend checking it."}, {"label": "Close", "text": "Arm out, patch on, \"still there.\" Then the night: patches on, one drink, the group."}]', '0:00 / 0:40 / 2:00. Still on.', 'Only post it if it really stays on. If it does not, tell us and do not post.', 'Say waterproof. The pack says water resistant.', NULL, 'Patch on the arm, the arm goes into the water, a timer starts on screen. Nobody talks.', 'Time jumps: 10 min, 40 min, 2 hours. The arm comes out each time. Still on.', 'Built on what buyers of every patch say in reviews: residue, ''adhesive very tacky'', falls off wet. Drdent''s best creator ad is 20 silent seconds of the strips working, then ''look at that''. Answer the objection on camera and go quiet while you do it.', '[{"brand": "Reviews of other patches", "what": "The objection in their own words: residue, tacky, falls off in water. Answer it on camera, do not argue with it.", "url": null}, {"brand": "Drdent", "what": "Twenty silent seconds of the product working, then a real reaction. Steal the quiet test.", "url": "https://app.tryatria.com/ad/m1563635778876692"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('3f3056f686d632e9', 'act_1033194534145987', '8d23caa34d96cec7', 0, 0, 29, 'live', 'My old routine cost $40', 'The drugstore run, the electrolyte sticks, the nap. Add it up, then put the patch on top of the receipt.', 'Women who have tried everything.', 'Party Patch', 'Voiceover', NULL, '["My old next-day routine took a drugstore run and a nap. Here''s the receipt.", "Forty dollars at CVS every time I went out. Now I spend this.", "Receipts from the old me. Let''s add it up."]', '[{"label": "Open · 0 to 3s", "text": "The receipt unrolling, the pack on top."}, {"label": "Middle", "text": "Each item from the bag beside its line on the receipt, the total climbing. Then the patch going on before a night out."}, {"label": "Close", "text": "The pack price from the site, said out loud, next to the total."}]', 'THEN: $40 and a nap. NOW: the price on the site.', 'Real prices only, from a real receipt.', 'Invent a discount. Say the price on the site the day you post.', NULL, 'A CVS receipt unrolling across the counter, then the patch pack set down on top of it.', 'The receipt lines get totaled on screen, one at a time, and the number keeps climbing.', 'Waterboy''s rising trade ad closes on ''my old routine required a small bank loan and a chemistry degree''. The cost of the old way sells without a single claim, and a climbing number is a rehook.', '[{"brand": "Waterboy", "what": "''My old routine required a small bank loan.'' Steal the cost-of-the-old-way frame and the climbing total.", "url": "https://app.tryatria.com/ad/m1058963726969933"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '9901f92436ad621b', 'act_1033194534145987', '3f3056f686d632e9', 'meta', '120249211680840266', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_1033194534145987' AND ad_id='120249211680840266') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='3f3056f686d632e9' AND ad_id='120249211680840266');
