UPDATE p_amb_brand SET display_name='Party Patch', intro='Party Patch is the patch you stick on before the night so tomorrow still happens. We want videos that look like your actual life: the girls, the kids, the calendar, the one drink at dinner. One rule before anything else: do something with your hands before you talk. Patch on, pile on the counter, pen on the calendar, then the first line. Pick one idea, film it your way, and submit it on TRYBE like always.', about='A vitamin-infused patch you put on before drinks, for a better next day. Scent-free, zero calories, water resistant, nothing to mix. Fun designs, and right now the Halloween bundle: three designs, two of each, six patches. Prices and offers change, so only ever say what is on the site the day you post.', audience='Women 30 to 50 with a full calendar. Moms, mostly. She is not trying to party harder. She wants the night out AND the 8am soccer game, the school run, the Sunday hike, the Christmas card photo. Talk to her like a friend at the bar, not like a wellness clinic.', accent='#1E88E5', avoid_json='[{"title": "Talking to camera about hangovers while putting a patch on, with a text overlay", "why": "This is most of what we get. It all looks the same and none of it stands out in the feed."}, {"title": "Lying in bed or on the couch looking hungover", "why": "We sell a better tomorrow, not a bad one. Show her up and doing the thing."}, {"title": "Shots, heavy drinking, or anyone who looks drunk", "why": "It breaks ad rules and it is not our customer. A drink in hand at dinner or a party is fine."}, {"title": "Reading the claims off the pack", "why": "Show the moment it helps. Nobody stops scrolling for an ingredient list."}, {"title": "An unboxing with no story", "why": "Unboxings only work when they are for something: the girls trip, the party tonight."}, {"title": "Talking to the camera while nothing happens", "why": "The four creator videos we ran this way were the worst ads on the account, every one of them. Your hands do something in the first second: patch on, pile on the counter, pen on the calendar. Then talk."}]', rules_json='["Say \"for a better next day\" or \"so tomorrow still happens\". Never say it cures, prevents or stops hangovers.", "Never say \"hangxiety\" and never mention anxiety, calm or stress. Every other brand says it; we cannot make that claim.", "The patch goes on BEFORE the night, on camera, where we can see it. Never show it going on the morning after.", "Keep the patch visible in at least one shot: arm, shoulder or hip.", "Everyone on screen is 21 or older. No drinking and driving, ever. Nobody looks drunk.", "Say \"water resistant\", never \"waterproof\". That is what the pack says.", "Reviews: only ones that are live on partypatch.com, read word for word, with the words on screen.", "Prices and offers: only say the price on the site the day you post. Never say a price for the Halloween bundle.", "Film vertical, sound on, and show where you are in the first two seconds.", "Only film people who have agreed to be in your video. Kids only with a parent''s okay, and never near a drink."]', season_json='{"title": "Halloween, then the holidays", "until": "Oct 31", "line": "Halloween is now: costume parties, the mom group chat, the Halloween bundle. Film your holiday videos in October too, so they are live on Nov 1. December is our biggest month of the year, and the videos that run in December get filmed now.", "next": "Friendsgiving, holiday parties and New Year''s Eve, from Nov 1", "highlight": ["10-06", "12-31"], "show_chart": true, "color": "#7C3AED"}', guide_json='[{"title": "Your hands first, then your mouth", "text": "Patch on the shoulder, the pile on the counter, the red pen on a Saturday. Then the first line. A face saying hello gets scrolled. A hand pressing a patch on gets watched."}, {"title": "Say who it is for in line one", "text": "\"If you drink wine and you have kids, this one is for you.\" The right woman stops. Everyone else scrolls, and that is fine."}, {"title": "Change the picture at 3 seconds", "text": "Bar at 9pm, then pancakes at 7am. Mirror, then the door. If you have been talking to the camera for five seconds without moving, cut."}, {"title": "Give them a number that keeps changing", "text": "Saturdays left this year: 11. The receipt total climbing. Nine girls, nine kits. If she is waiting for the next number, she stays."}, {"title": "Go quiet when you test it", "text": "Arm in the hot tub, timer on, say nothing. Let the camera watch it stay on, then react for real. The quiet is the proof."}, {"title": "The gripe goes in the middle, not the start", "text": "Open on the night or the patch. Bring in \"two glasses costs me a weekend now\" once they are already watching. And never open on the bad morning; we do not show it at all."}, {"title": "End on her, and what to do", "text": "Up at 7, soccer, pancakes, the boat, patch on the wrist. Then, in your own words: who it is for and where to get it. No \"link below\", no wrap-up speech."}, {"title": "No logo, no \"hey guys\", no sponsored card", "text": "The brand shows up in your hands and in the story, never as a title slide. Start like you are mid-thought with a friend: \"So I counted the Saturdays I lost last year.\""}]', updated_at=datetime('now') WHERE act_id='act_1033194534145987';
